use vstd::prelude::*;

verus! {

    // A NumPy‐like scalar data type
    #[verifier(publish)]
    #[derive(PartialEq, Eq, Clone, Copy)]
    enum NumpyScalarType {
        Int64,
        Float64,
        Complex128,
        String,
        Bool,
    }

    // A NumPy‐like object: scalars, arrays, or generic
    #[verifier(publish)]
    #[derive(PartialEq, Eq)]
    enum NumpyObject {
        Int(i64),
        Float(f64),
        ArrayInt(Vec<i64>),
        ArrayFloat(Vec<f64>),
        ArrayComplex(Vec<(f64, f64)>), // each pair is a complex number
        Str(String),
        Bool(bool),
        Generic,
    }

    // Map an object to its scalar type, using `default` only if `rep` is Generic.
    fn obj2sctype(
        rep: NumpyObject,
        default: Option<NumpyScalarType>
    ) -> (res: Option<NumpyScalarType>)
        ensures
            // For each non‐generic variant, we return the corresponding scalar type
            match rep {
                NumpyObject::Int(_)           => res == Some(NumpyScalarType::Int64),
                NumpyObject::Float(_)         => res == Some(NumpyScalarType::Float64),
                NumpyObject::ArrayInt(_)      => res == Some(NumpyScalarType::Int64),
                NumpyObject::ArrayFloat(_)    => res == Some(NumpyScalarType::Float64),
                NumpyObject::ArrayComplex(_)  => res == Some(NumpyScalarType::Complex128),
                NumpyObject::Str(_)           => res == Some(NumpyScalarType::String),
                NumpyObject::Bool(_)          => res == Some(NumpyScalarType::Bool),
                // For Generic, we return exactly the default (which may be None)
                NumpyObject::Generic          => res == default,
            }
    {
        // A simple match implementing the above specification
        match rep {
            NumpyObject::Int(_)           => Some(NumpyScalarType::Int64),
            NumpyObject::Float(_)         => Some(NumpyScalarType::Float64),
            NumpyObject::ArrayInt(_)      => Some(NumpyScalarType::Int64),
            NumpyObject::ArrayFloat(_)    => Some(NumpyScalarType::Float64),
            NumpyObject::ArrayComplex(_)  => Some(NumpyScalarType::Complex128),
            NumpyObject::Str(_)           => Some(NumpyScalarType::String),
            NumpyObject::Bool(_)          => Some(NumpyScalarType::Bool),
            NumpyObject::Generic          => default,  // use default (may be None)
        }
    }
}

fn main() {
    // Example usage (not part of the verification)
    let o1 = NumpyObject::Int(42);
    let t1 = obj2sctype(o1, None);
    assert!(t1 == Some(NumpyScalarType::Int64));

    let o2 = NumpyObject::Generic;
    let t2 = obj2sctype(o2, Some(NumpyScalarType::Float64));
    assert!(t2 == Some(NumpyScalarType::Float64));

    let o3 = NumpyObject::Generic;
    let t3 = obj2sctype(o3, None);
    assert!(t3.is_none());
}